import {s,connect,message} from '../accounts.mjs';
const $=id=>document.getElementById(id);let b,rows=[];
function note(t){$('message').textContent=t}
async function load(){const result=await s.getDocs(s.query(s.collection(b.db,'customerAccounts'),s.limit(1000)));rows=result.docs.map(x=>({id:x.id,...x.data()}));render();note('מוצגים עד 1,000 לקוחות')}
function localDate(ms){const d=new Date(ms);return new Date(ms-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function render(){
 $('cards').replaceChildren();const term=$('search').value.trim().toLowerCase();
 for(const a of rows.filter(a=>(a.businessName+' '+a.email).toLowerCase().includes(term))){
  const card=document.createElement('section'),h=document.createElement('h2'),p=document.createElement('p');h.textContent=a.businessName;p.textContent=[a.email,a.status,a.expiresAt?'עד '+new Date(a.expiresAt).toLocaleString('he-IL'):'ללא תוקף',`ספירות: ${Number(a.countsUsed)||0} מתוך ${Number(a.countLimit)||0}`].join(' · ');card.append(h,p);
  const quotaLabel=document.createElement('label');quotaLabel.textContent='מכסה כוללת של ספירות';const quotaInput=document.createElement('input');quotaInput.type='number';quotaInput.min=Number(a.countsUsed)||0;quotaInput.max=100000;quotaInput.step='1';quotaInput.value=Number.isSafeInteger(a.countLimit)?a.countLimit:0;quotaLabel.append(quotaInput);card.append(quotaLabel);
  const usedLabel=document.createElement('label');usedLabel.textContent='ספירות שכבר נוצלו (לצורך מעבר לרישוי החדש)';const usedInput=document.createElement('input');usedInput.type='number';usedInput.min='0';usedInput.max=100000;usedInput.step='1';usedInput.value=Number.isSafeInteger(a.countsUsed)?a.countsUsed:0;usedLabel.append(usedInput);card.append(usedLabel);
  if(typeof a.number==='string'&&a.number.trim()){const clearNumber=document.createElement('button');clearNumber.textContent='מחיקת מספר מזהה ישן מהשרת';clearNumber.onclick=async()=>{if(!confirm('למחוק את מספר העוסק/ח.פ. הישן שנשמר בשרת? הוא יישאר רק בפרטי העסק המקומיים במכשיר, אם הוזן שם.'))return;clearNumber.disabled=true;try{await s.updateDoc(s.doc(b.db,'customerAccounts',a.id),{number:'',countLimit:Number.isSafeInteger(a.countLimit)?a.countLimit:0,countsUsed:Number.isSafeInteger(a.countsUsed)?a.countsUsed:0,lastClaimId:a.lastClaimId||'',updatedAt:s.serverTimestamp()});await load();note('המספר הישן נמחק מהחשבון בשרת')}catch(e){note(message(e))}finally{clearNumber.disabled=false}};card.append(clearNumber)}
  const saveQuota=document.createElement('button');saveQuota.textContent='שמירת מכסה';saveQuota.onclick=async()=>{saveQuota.disabled=true;try{const limit=Number(quotaInput.value),used=Number(usedInput.value);if(!Number.isSafeInteger(limit)||!Number.isSafeInteger(used)||used<0||limit<used||limit>100000)throw Error('המכסה והשימוש חייבים להיות מספרים שלמים תקינים, והמכסה לא יכולה להיות קטנה מהשימוש');await s.updateDoc(s.doc(b.db,'customerAccounts',a.id),{countLimit:limit,countsUsed:used,lastClaimId:a.lastClaimId||'',updatedAt:s.serverTimestamp()});await load();note('מכסת הספירות נשמרה')}catch(e){note(message(e))}finally{saveQuota.disabled=false}};card.append(saveQuota);
  const extraLabel=document.createElement('label');extraLabel.textContent='כמה ספירות להוסיף';const extraInput=document.createElement('input');extraInput.type='number';extraInput.min='1';extraInput.max='100000';extraInput.step='1';extraInput.value='1';extraLabel.append(extraInput);card.append(extraLabel);
  const add=document.createElement('button');add.textContent='הוסף ספירה לרישיון';add.onclick=async()=>{add.disabled=true;try{const amount=Number(extraInput.value),limit=Number.isSafeInteger(a.countLimit)?a.countLimit:0,used=Number(a.countsUsed)||0;if(!Number.isSafeInteger(amount)||amount<1||limit+amount>100000)throw Error('בחר מספר שלם של ספירות להוספה');const patch={countLimit:limit+amount,countsUsed:used,lastClaimId:a.lastClaimId||'',updatedAt:s.serverTimestamp()};await s.updateDoc(s.doc(b.db,'customerAccounts',a.id),patch);await load();note(`נוספו ${amount} ספירות לרישיון`)}catch(e){note(message(e))}finally{add.disabled=false}};card.append(add);
  const expiryLabel=document.createElement('label');expiryLabel.textContent='תוקף לפי השעה המקומית במכשיר המנהל';const expiry=document.createElement('input');expiry.type='datetime-local';expiry.value=localDate(a.expiresAt>Date.now()?a.expiresAt:Date.now()+30*86400000);expiryLabel.append(expiry);card.append(expiryLabel);
  for(const [text,status] of [['פתיחה / הארכת תוקף','active'],['חסימה','blocked']]){const button=document.createElement('button');button.textContent=text;button.onclick=async()=>{button.disabled=true;try{const end=new Date(expiry.value).getTime();if(!Number.isFinite(end)||end<=Date.now())throw Error('בחר תוקף עתידי');await s.updateDoc(s.doc(b.db,'customerAccounts',a.id),{status,expiresAt:end,countLimit:Number.isSafeInteger(a.countLimit)?a.countLimit:0,countsUsed:Number(a.countsUsed)||0,lastClaimId:a.lastClaimId||'',updatedAt:s.serverTimestamp()});await load();note(status==='active'?'תוקף החשבון עודכן; מכסת הספירות נשמרה בנפרד':'החשבון נחסם')}catch(e){note(message(e))}finally{button.disabled=false}};card.append(button)}
  $('cards').append(card)
 }
}
async function enter(){const owner=await s.getDocFromServer(s.doc(b.db,'settings','accountOwner'));if(owner.data()?.uid!==b.auth.currentUser?.uid)throw Error('לחשבון זה אין הרשאת מנהל');$('login').hidden=true;$('panel').hidden=false;await load()}
$('login').onsubmit=async e=>{e.preventDefault();try{b=await connect(true);await s.signInWithEmailAndPassword(b.auth,$('login').elements.email.value.trim(),$('login').elements.password.value);await enter()}catch(e){note(message(e))}};
$('logout').onclick=async()=>{await s.signOut(b.auth);location.reload()};$('refresh').onclick=()=>load().catch(e=>note(message(e)));$('search').oninput=render;
connect(true).then(async c=>{b=c;if(b.auth.currentUser)await enter()}).catch(e=>note(message(e)));
